package io.github.akanshsirohi.quadqr;

import org.json.JSONObject;

public final class ScanOptions {
    final Integer minVersion,maxVersion,maxFinderCandidates,locatorMaxDimension,workingMaxDimension,softMaxCells,softPairCells; final Double structuralTolerance,sampleRadius,highDensitySampleRadius,maxErasureConfidence,softConfidenceThreshold; final Boolean axisAlignedFallback,finderRecovery,rotationRecovery,softDecoding;
    private ScanOptions(Builder b){minVersion=b.minVersion;maxVersion=b.maxVersion;maxFinderCandidates=b.maxFinderCandidates;locatorMaxDimension=b.locatorMaxDimension;workingMaxDimension=b.workingMaxDimension;softMaxCells=b.softMaxCells;softPairCells=b.softPairCells;structuralTolerance=b.structuralTolerance;sampleRadius=b.sampleRadius;highDensitySampleRadius=b.highDensitySampleRadius;maxErasureConfidence=b.maxErasureConfidence;softConfidenceThreshold=b.softConfidenceThreshold;axisAlignedFallback=b.axisAlignedFallback;finderRecovery=b.finderRecovery;rotationRecovery=b.rotationRecovery;softDecoding=b.softDecoding;}
    public static Builder builder(){return new Builder();} public static ScanOptions defaults(){return builder().build();}
    public static final class Builder {
        Integer minVersion,maxVersion,maxFinderCandidates,locatorMaxDimension,workingMaxDimension,softMaxCells,softPairCells; Double structuralTolerance,sampleRadius,highDensitySampleRadius,maxErasureConfidence,softConfidenceThreshold; Boolean axisAlignedFallback,finderRecovery,rotationRecovery,softDecoding;
        public Builder minVersion(int v){minVersion=v;return this;} public Builder maxVersion(int v){maxVersion=v;return this;} public Builder maxFinderCandidates(int v){maxFinderCandidates=v;return this;} public Builder locatorMaxDimension(int v){locatorMaxDimension=v;return this;} public Builder workingMaxDimension(int v){workingMaxDimension=v;return this;}
        public Builder structuralTolerance(double v){structuralTolerance=v;return this;} public Builder axisAlignedFallback(boolean v){axisAlignedFallback=v;return this;} public Builder finderRecovery(boolean v){finderRecovery=v;return this;} public Builder rotationRecovery(boolean v){rotationRecovery=v;return this;}
        public Builder sampleRadius(double v){sampleRadius=v;return this;} public Builder highDensitySampleRadius(double v){highDensitySampleRadius=v;return this;} public Builder maxErasureConfidence(double v){maxErasureConfidence=v;return this;} public Builder softDecoding(boolean v){softDecoding=v;return this;} public Builder softConfidenceThreshold(double v){softConfidenceThreshold=v;return this;} public Builder softMaxCells(int v){softMaxCells=v;return this;} public Builder softPairCells(int v){softPairCells=v;return this;}
        public ScanOptions build(){return new ScanOptions(this);}
    }
    JSONObject toJson(){try{JSONObject o=new JSONObject();if(minVersion!=null)o.put("minVersion",minVersion);if(maxVersion!=null)o.put("maxVersion",maxVersion);if(maxFinderCandidates!=null)o.put("maxFinderCandidates",maxFinderCandidates);if(locatorMaxDimension!=null)o.put("locatorMaxDimension",locatorMaxDimension);if(workingMaxDimension!=null)o.put("workingMaxDimension",workingMaxDimension);if(structuralTolerance!=null)o.put("structuralTolerance",structuralTolerance);if(axisAlignedFallback!=null)o.put("axisAlignedFallback",axisAlignedFallback);if(finderRecovery!=null)o.put("finderRecovery",finderRecovery);if(rotationRecovery!=null)o.put("rotationRecovery",rotationRecovery);if(sampleRadius!=null)o.put("sampleRadius",sampleRadius);if(highDensitySampleRadius!=null)o.put("highDensitySampleRadius",highDensitySampleRadius);if(maxErasureConfidence!=null)o.put("maxErasureConfidence",maxErasureConfidence);if(softDecoding!=null)o.put("softDecoding",softDecoding);if(softConfidenceThreshold!=null)o.put("softConfidenceThreshold",softConfidenceThreshold);if(softMaxCells!=null)o.put("softMaxCells",softMaxCells);if(softPairCells!=null)o.put("softPairCells",softPairCells);return o;}catch(Exception e){throw new QuadQRException(e.getMessage(),e);}}
}
